70	                  requestGroup->getFirstFilePath().c_str()));
71	  std::unique_ptr<ValueBase> torrent;
72	  if (requestGroup->inMemoryDownload()) {
73	    auto& dw = static_cast<AbstractSingleDiskAdaptor*>(
74	                   requestGroup->getPieceStorage()->getDiskAdaptor().get())
75	                   ->getDiskWriter();
76	    auto bdw = static_cast<bittorrent::BencodeDiskWriter*>(dw.get());
77	    int error = bdw->finalize();
78	    if (error == 0) {
79	      torrent = bdw->getResult();
80	    }
81	  }
82	  else {
83	    std::string content;
84	    try {
85	      requestGroup->getPieceStorage()->getDiskAdaptor()->openExistingFile();
86	      content =
87	          util::toString(requestGroup->getPieceStorage()->getDiskAdaptor());
88	      requestGroup->getPieceStorage()->getDiskAdaptor()->closeFile();
89	    }
90	    catch (Exception& e) {
91	      requestGroup->getPieceStorage()->getDiskAdaptor()->closeFile();
92	      throw;
93	    }
94	    ssize_t error;
95	    torrent = bittorrent::ValueBaseBencodeParser().parseFinal(
96	        content.c_str(), content.size(), error);
97	  }
98	  if (!torrent) {
99	    throw DL_ABORT_EX2("Could not parse BitTorrent metainfo",
100	                       error_code::BENCODE_PARSE_ERROR);
101	  }
102	  std::vector<std::shared_ptr<RequestGroup>> newRgs;
103	  createRequestGroupForBitTorrent(newRgs, requestGroup->getOption(),
104	                                  std::vector<std::string>(), "",
105	                                  torrent.get());
106	  requestGroup->followedBy(std::begin(newRgs), std::end(newRgs));
107	  for (auto& rg : newRgs) {
108	    rg->following(requestGroup->getGID());
109	  }
110	  auto mi = createMetadataInfoFromFirstFileEntry(
111	      requestGroup->getGroupId(), requestGroup->getDownloadContext());
112	  if (mi) {
113	    setMetadataInfo(std::begin(newRgs), std::end(newRgs), mi);
114	  }
