62	
63	bool SeedCheckCommand::execute()
64	{
65	  if (btRuntime_->isHalt()) {
66	    return true;
67	  }
68	  if (!seedCriteria_.get()) {
69	    return false;
70	  }
71	  if (!checkStarted_) {
72	    if (pieceStorage_->downloadFinished()) {
73	      checkStarted_ = true;
74	      seedCriteria_->reset();
75	    }
76	  }
77	  if (checkStarted_) {
78	    if (seedCriteria_->evaluate()) {
79	      A2_LOG_NOTICE(MSG_SEEDING_END);
80	      btRuntime_->setHalt(true);
81	    }
82	  }
83	  e_->addCommand(std::unique_ptr<Command>(this));
84	  return false;
85	}
